<script>
(() => {
const root=document.querySelector('[data-activity-rooms]');if(!root)return;const rooms=[],endedAudioIds=new Set(),previousStatuses=new Map(),presetDurations=[15,30,45,60,90,120];let nextId=1,audioContext=null,audioEnabled=false;const nowFormatter=new Intl.DateTimeFormat('nb-NO',{timeZone:'Europe/Oslo',weekday:'long',day:'2-digit',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}),partsFormatter=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}),roomGrid=root.querySelector('[data-room-grid]'),nowElement=root.querySelector('[data-current-time]'),soundStatus=root.querySelector('[data-sound-status]');
const osloParts=()=>Object.fromEntries(partsFormatter.formatToParts(new Date()).filter(x=>x.type!=='literal').map(x=>[x.type,Number(x.value)]));const timelineNow=()=>{const p=osloParts();return Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute,p.second)};const timeToMinutes=time=>{const m=/^(\d{2}):(\d{2})$/.exec(time||'');return !m||Number(m[1])>23||Number(m[2])>59?null:Number(m[1])*60+Number(m[2])};const timeFromMinutes=m=>String(Math.floor((m%1440+1440)%1440/60)).padStart(2,'0')+':'+String((m%60+60)%60).padStart(2,'0');const startAllowed=time=>{const m=timeToMinutes(time);return m!==null&&m>=420&&m<=1200};const times=b=>{const m=timeToMinutes(b.start),p=osloParts(),start=Date.UTC(p.year,p.month-1,p.day,Math.floor(m/60),m%60);return{start:start,end:start+b.duration*60000}};const status=b=>{const t=times(b),now=timelineNow();return now<t.start?'upcoming':now<t.end?'ongoing':'finished'};const statusText=b=>{const s=status(b);if(s==='upcoming')return'Kommende';if(s==='ongoing')return'Pågår – '+Math.max(0,Math.ceil((times(b).end-timelineNow())/60000))+' min igjen';return b.acknowledged?'Ferdig – kvittert':'Tiden er ute – kvitter'};const overlaps=(room,candidate,exceptId)=>room.bookings.some(b=>b.id!==exceptId&&times(candidate).start<times(b).end&&times(b).start<times(candidate).end);const button=(label,classes,action)=>{const el=document.createElement('button');el.type='button';el.className=classes;el.textContent=label;el.addEventListener('click',action);return el};
const tone=()=>{if(!audioEnabled||!audioContext)return;const o=audioContext.createOscillator(),g=audioContext.createGain();o.frequency.value=880;g.gain.setValueAtTime(.08,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.25);o.connect(g).connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+.25)};const enableSound=async()=>{try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();await audioContext.resume();audioEnabled=true;tone();soundStatus.textContent='Lyd er aktivert. Kort testtone spilt.'}catch(_){soundStatus.textContent='Kunne ikke aktivere lyd i denne nettleseren.'}};
function refreshLiveData(){nowElement.textContent=nowFormatter.format(new Date()).replace(/^./,x=>x.toUpperCase());rooms.forEach(room=>room.bookings.forEach(b=>{const key=room.id+'-'+b.id,row=roomGrid.querySelector('[data-booking-id="'+key+'"]');if(!row)return;const s=status(b),tag=row.querySelector('[data-booking-status]');row.classList.toggle('booking-row--expired',s==='finished'&&!b.acknowledged);tag.className='booking-status booking-status--'+s;tag.textContent=statusText(b);const old=previousStatuses.get(key);if(s==='finished'&&old&&old!=='finished'&&!endedAudioIds.has(key)){endedAudioIds.add(key);tone()}previousStatuses.set(key,s)}))}
function start(form){return form.querySelector('[name="manual_start"]').value||form.querySelector('[name="start_preset"]').value}function duration(form){return form.querySelector('[name="duration_preset"]').value==='custom'?Number(form.querySelector('[name="duration_custom"]').value):Number(form.querySelector('[name="duration_preset"]').value)}function updateEnd(form){const s=start(form),d=duration(form);form.querySelector('[data-end-time]').textContent=timeToMinutes(s)===null||!Number.isFinite(d)||d<1?'Sluttid vises når starttid og varighet er oppgitt.':'Beregnet sluttid: '+timeFromMinutes(timeToMinutes(s)+d)}function updateCustom(form){const field=form.querySelector('[name="duration_custom"]'),custom=form.querySelector('[name="duration_preset"]').value==='custom';field.closest('label').hidden=!custom;field.required=custom;updateEnd(form)}function applyBooking(form,b){const p=form.querySelector('[name="start_preset"]'),m=form.querySelector('[name="manual_start"]'),d=form.querySelector('[name="duration_preset"]'),c=form.querySelector('[name="duration_custom"]');form.querySelector('[name="person"]').value=b.person;p.value=Array.from(p.options).some(o=>o.value===b.start)?b.start:'';m.value=p.value?'':b.start;d.value=presetDurations.includes(b.duration)?String(b.duration):'custom';c.value=d.value==='custom'?b.duration:'';updateCustom(form)}
function save(room,b,form,message){const person=form.querySelector('[name="person"]').value.trim(),s=start(form),d=duration(form);if(!person){message.textContent='Skriv hvem som skal bruke rommet.';return}if(!startAllowed(s)){message.textContent='Starttid må være mellom 07:00 og 20:00.';return}if(!Number.isInteger(d)||d<1||d>1440){message.textContent='Varighet må være et helt antall minutter fra 1 til 1440.';return}const entry={id:b?b.id:nextId++,person:person,start:s,duration:d,acknowledged:b?b.acknowledged:false},warning=overlaps(room,entry,b&&b.id)?'Booking lagret. Den overlapper med en annen booking i dette rommet.':'';if(b)Object.assign(b,entry);else room.bookings.push(entry);renderRooms();if(warning)roomGrid.querySelector('[data-room-id="'+room.id+'"] [data-booking-message]').textContent=warning}
function startOptions(){let html='<option value="">Velg starttid</option>';for(let m=420;m<=1200;m+=15){const value=timeFromMinutes(m);html+='<option value="'+value+'">'+value+'</option>'}return html}
function formMarkup(){return '<label>Hvem skal bruke rommet?<input name="person" type="text" maxlength="120" required></label><label>Starttid<select name="start_preset" required>'+startOptions()+'</select></label><label>eller skriv starttid manuelt<input name="manual_start" type="time" min="07:00" max="20:00" step="60"></label><p class="booking-form__hint">Starttid kan være fra 07:00 til 20:00.</p><label>Varighet<select name="duration_preset"><option value="15">15 minutter</option><option value="30">30 minutter</option><option value="45">45 minutter</option><option value="60" selected>1 time</option><option value="90">1 time 30 minutter</option><option value="120">2 timer</option><option value="custom">Egendefinert</option></select></label><label hidden>Egendefinert varighet (minutter)<input name="duration_custom" type="number" min="1" max="1440" step="1"></label><p class="booking-form__end" data-end-time></p><div class="booking-form__actions"><button class="btn btn-primary activity-room-btn" type="submit" data-save-booking>Legg til booking</button><button class="btn btn-outline-secondary activity-room-btn" type="button" data-cancel-edit hidden>Avbryt</button></div><p class="booking-form__message" data-booking-message aria-live="polite"></p>'}
function roomCard(room){const card=document.createElement('section');card.className='room-card';card.dataset.roomId=room.id;const header=document.createElement('header'),heading=document.createElement('h2'),actions=document.createElement('div');header.className='room-card__header';heading.textContent=room.name;actions.className='room-card__actions';actions.append(button('Endre navn','activity-room-btn activity-room-btn--light',()=>{const name=window.prompt('Nytt navn på rommet:',room.name);if(name!==null&&name.trim()){room.name=name.trim().slice(0,80);renderRooms()}}),button('Slett rom','activity-room-btn activity-room-btn--danger',()=>{if(window.confirm('Slette '+room.name+' med alle bookingene?')){rooms.splice(rooms.indexOf(room),1);renderRooms()}}));header.append(heading,actions);const body=document.createElement('div'),form=document.createElement('form');body.className='room-card__body';form.className='booking-form';form.noValidate=true;form.innerHTML=formMarkup();form.addEventListener('submit',e=>{e.preventDefault();save(room,room.bookings.find(b=>String(b.id)===form.dataset.editingId),form,form.querySelector('[data-booking-message]'))});form.querySelectorAll('select,input').forEach(el=>el.addEventListener('input',()=>el.name==='duration_preset'?updateCustom(form):updateEnd(form)));form.querySelector('[data-cancel-edit]').addEventListener('click',()=>{form.reset();form.dataset.editingId='';form.querySelector('[data-save-booking]').textContent='Legg til booking';form.querySelector('[data-cancel-edit]').hidden=true;form.querySelector('[data-booking-message]').textContent='';updateCustom(form)});updateEnd(form);body.append(form);const list=document.createElement('ul');list.className='booking-list';room.bookings.sort((a,b)=>timeToMinutes(a.start)-timeToMinutes(b.start)).forEach(b=>{const s=status(b),key=room.id+'-'+b.id,row=document.createElement('li'),time=document.createElement('div'),desc=document.createElement('div'),person=document.createElement('div'),meta=document.createElement('div'),tag=document.createElement('span'),rowActions=document.createElement('div');row.className='booking-row'+(s==='finished'&&!b.acknowledged?' booking-row--expired':'');row.dataset.bookingId=key;time.className='booking-time';time.textContent=b.start+'–'+timeFromMinutes(timeToMinutes(b.start)+b.duration);person.className='booking-person';person.textContent=b.person;meta.className='booking-meta';meta.textContent=b.duration+' minutter'+(overlaps(room,b,b.id)?' · Overlapper annen booking':'');tag.dataset.bookingStatus='';tag.className='booking-status booking-status--'+s;tag.textContent=statusText(b);desc.append(person,meta,tag);rowActions.className='booking-actions';rowActions.append(button('Endre','btn btn-outline-primary activity-room-btn',()=>{applyBooking(form,b);form.dataset.editingId=b.id;form.querySelector('[data-save-booking]').textContent='Lagre endring';form.querySelector('[data-cancel-edit]').hidden=false;form.querySelector('[name="person"]').focus()}));if(s==='finished'&&!b.acknowledged)rowActions.append(button('Kvitter ut','btn btn-warning activity-room-btn',()=>{b.acknowledged=true;renderRooms()}));rowActions.append(button('Slett','btn btn-outline-danger activity-room-btn',()=>{if(window.confirm('Slette denne bookingen?')){room.bookings.splice(room.bookings.indexOf(b),1);renderRooms()}}));row.append(time,desc,rowActions);list.append(row)});if(room.bookings.length)body.append(list);else{const empty=document.createElement('p');empty.className='booking-empty';empty.textContent='Ingen bookinger ennå.';body.append(empty)}card.append(header,body);return card}
function renderRooms(){roomGrid.replaceChildren(...rooms.map(roomCard));refreshLiveData()}
root.querySelector('[data-add-room]').addEventListener('click',()=>{const input=root.querySelector('[data-new-room-name]'),name=input.value.trim();if(!name){input.setCustomValidity('Skriv et navn på rommet eller aktiviteten.');input.reportValidity();return}input.setCustomValidity('');rooms.push({id:nextId++,name:name.slice(0,80),bookings:[]});input.value='';renderRooms()});root.querySelector('[data-new-room-name]').addEventListener('input',e=>e.target.setCustomValidity(''));root.querySelector('[data-enable-sound]').addEventListener('click',enableSound);const feedback=root.querySelector('[data-activity-feedback]');feedback.addEventListener('submit',async e=>{e.preventDefault();const error=feedback.querySelector('[data-feedback-message]'),success=feedback.querySelector('[data-feedback-success]'),submit=feedback.querySelector('[data-feedback-submit]');error.textContent='';success.hidden=true;if(!feedback.reportValidity())return;submit.disabled=true;try{const response=await fetch(root.dataset.feedbackUrl,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':root.dataset.csrfToken},body:JSON.stringify(Object.fromEntries(new FormData(feedback)))}),data=await response.json();if(!response.ok){error.textContent=Object.values(data.errors||{}).flat().join(' ')||'Kunne ikke sende tilbakemeldingen. Prøv igjen.';return}feedback.reset();success.textContent=data.message;success.hidden=false}catch(_){error.textContent='Kunne ikke sende tilbakemeldingen. Teksten er beholdt, så du kan prøve igjen.'}finally{submit.disabled=false}});window.addEventListener('beforeunload',e=>{if(rooms.length){e.preventDefault();e.returnValue=''}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshLiveData()});window.setInterval(refreshLiveData,1000);renderRooms();
})();
</script>
